let _pass = 0;
let _fail = 0;
function _test(num: number, got, expected) {
  const passed = got === expected;
  console.log('---------------------');
  console.log('Test ' + num + ':');
  console.log('Output: ' + got);
  console.log(passed ? 'Pass' : 'Fail');
  if (passed) _pass++; else _fail++;
}
const vid1 = new Video('Intro', 10);
const pl1 = new Playlist('Top Hits', 5);
_test(1, vid1.describe(), 'Video "Intro" is 10 minutes long');
_test(2, pl1.describe(), 'Playlist "Top Hits" has 5 videos');
const vid2 = new Video('Deep Dive', 42);
const pl2 = new Playlist('Favorites', 12);
_test(3, vid2.describe(), 'Video "Deep Dive" is 42 minutes long');
_test(4, pl2.describe(), 'Playlist "Favorites" has 12 videos');
console.log('---------------------');
console.log(_pass + ' passed, ' + _fail + ' failed');

